mapper.select:
SELECT o.event_id FROM nw_chat_session_outbox o
WHERE o.tenant_id=#{tenantId} AND o.session_id=#{sessionId}
ORDER BY o.session_sequence DESC LIMIT 1

SELECT d.id, d.tenant_id, d.subscription_id, d.outbox_event_id, d.event_id,
       d.session_id, d.session_sequence, d.status, d.attempts, d.available_at,
       d.claimed_at, d.delivered_at, d.error_code, d.created_at, d.updated_at
FROM public.nw_chat_session_outbox_webhook_deliveries d
INNER JOIN public.nw_chat_session_outbox o
  ON o.tenant_id = d.tenant_id AND o.id = d.outbox_event_id
WHERE o.tenant_id = #{tenantId}
  AND o.session_id = #{sessionId}
  AND o.runtime_run_id = #{runtimeRunId}
  AND d.status = 'unresolved'
ORDER BY d.updated_at DESC, d.id DESC
LIMIT #{limit}
